pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 newMin) public {
        // 1. Keep domain wide — no assume/bound needed for uint256
        // 2. Setup: initialize the contract first
        c.Initialized();
        uint256 beforeMin = c.MinSum();

        // 3. Try to call SetMinSum — it should revert because initialized is true
        bool ok;
        try c.SetMinSum(newMin) { ok = true; } catch { ok = false; }

        uint256 afterMin = c.MinSum();
        // 4. General rule: If SetMinSum succeeded (did not revert), MinSum must remain unchanged.
        //    The reference ensures this by reverting; the mutant writes before revert, so a success means MinSum changed.
        assertTrue(!ok || afterMin == beforeMin);
    }
}

