pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 val1, uint256 val2) public {
        // Bound to avoid overflow issues, keep domain wide
        val1 = bound(val1, 0, type(uint256).max - 1);
        val2 = bound(val2, 0, type(uint256).max - 1);

        // Initialize the contract
        c.Initialized();

        // Record MinSum before any SetMinSum
        uint256 beforeVal = c.MinSum();

        // Try to call SetMinSum and check if it reverts
        bool ok;
        try c.SetMinSum(val1) { ok = true; } catch { ok = false; }

        // If it did not revert, MinSum must remain unchanged
        if (ok) {
            assertTrue(c.MinSum() == beforeVal);
        } else {
            // If it did revert, we have nothing to assert about MinSum change,
            // but we can still assert something trivial like true
            assertTrue(true);
        }
    }
}

