pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialVal, uint256 newVal) public {
        vm.assume(initialVal != newVal);
        c.Initialized();
        // Set initial MinSum before initialization is possible only by deploying a fresh contract.
        // But here c is already initialized. So we need to set MinSum before init?
        // Actually, in the reference, once initialized, SetMinSum always reverts and doesn't change MinSum.
        // In bug, SetMinSum changes MinSum then reverts.
        // To have a pre-call value, we can set MinSum before initialization by calling SetMinSum then Initialized.
        // Let's redeploy and do that.
        // Re-deploy to have a clean state.
        c = new C();
        c.SetMinSum(initialVal);
        c.Initialized();
        uint256 preCallMinSum = c.MinSum();
        // Now call SetMinSum with newVal - this should revert in both, but in bug, MinSum changes.
        vm.prank(address(this));
        try c.SetMinSum(newVal) {
            // should not succeed; but if it does, we don't care.
        } catch {
            // expected revert.
        }
        uint256 postCallMinSum = c.MinSum();
        assertTrue(preCallMinSum == postCallMinSum);
    }
}

