pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 preVal, uint256 newVal) public {
        // 1. initialize the contract
        c.Initialized();
        // Set an initial MinSum with a call that reverts (post-initialization, so it reverts)
        vm.prank(address(0x1234));
        // We need a call that reverts but we want to observe MinSum before and after
        // In reference: revert leaves MinSum unchanged (remains 0). In buggy: MinSum is written before revert, so it changes.
        uint256 beforeVal = c.MinSum();
        vm.prank(address(0x1234));
        try c.SetMinSum(preVal) { } catch { }
        uint256 afterVal = c.MinSum();
        // Rule: if the call reverted, MinSum must be unchanged.
        // We cannot assert revert inside the test without expectRevert, so we wrap in try/catch and check that if it reverted, afterVal == beforeVal.
        // To know if it reverted, we use a boolean flag.
        bool reverted;
        beforeVal = c.MinSum();
        vm.prank(address(0x5678));
        try c.SetMinSum(newVal) { reverted = false; } catch { reverted = true; }
        afterVal = c.MinSum();
        // Since initialized is true, the call always reverts in both versions. But in buggy, MinSum changes despite revert.
        // Assert: if the call reverted, MinSum must equal beforeVal.
        assertTrue(!reverted || afterVal == beforeVal);
    }
}

