pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address logAddress, uint256 putAmount) public {
        vm.assume(logAddress != address(0));
        vm.assume(putAmount > 0);

        // Deploy a legitimate LogFile that will be used by the reference
        LogFile log = new LogFile();

        // Initialize the contract
        c.Initialized();

        // Set the log file to the legitimate one
        c.SetLogFile(address(log));

        // Now attempt an operation that will call Log.AddMessage internally
        vm.deal(address(this), putAmount);
        c.Put{value: putAmount}(0);

        // The reference contract should have successfully added a message to the legitimate log
        // The mutant, having Log at address(0), will either revert or not update the log.
        // We check that the legitimate log's History length is greater than 0, indicating the operation succeeded.
        assertTrue(log.History(0).Val > 0);
    }
}

contract LogFile
{
    struct Message
    {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;

    Message LastMsg;

    function AddMessage(address _adr,uint _val, string memory _data)
    public
    {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

