// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 lockTime1, uint256 lockTime2, uint256 collectAmt) public {
        // Admissible domain: lockTime1, lockTime2 unlimited; collectAmt <= type(uint256).max
        // Deploy and initialize the contract
        c.SetMinSum(0);
        c.SetLogFile(address(this)); // LogFile not critical for property
        c.Initialized();

        // Setup actor
        address actor = address(0x1000);
        vm.deal(actor, 1 ether);

        // First Put with lockTime1
        vm.prank(actor);
        c.Put{value: 1 ether}(lockTime1);

        // Record unlockTime after first Put (correct: only updated if later)
        // We can't directly inspect internal state, but we can infer from Collect behavior.
        // The property: after two Puts with different lockTimes, if the second lockTime would set an
        // earlier unlockTime, the correct contract preserves the later one, while mutant overwrites it.
        // This means that after the second Put, a Collect may succeed earlier in the mutant than in the correct version.
        // To observe: warp to a time when correct should still be locked but mutant allows Collect.
        // We need to ensure lockTime2 results in an earlier unlockTime than lockTime1.
        // Step 1: Put with a longer lockTime
        // Step 2: Put with a shorter lockTime
        // Correct: unlockTime remains the longer one; Mutant: unlockTime becomes the shorter one.
        // Then warp to a time between the two and test Collect.

        // Constraint: lockTime2 + block.timestamp < lockTime1 + block.timestamp
        // Since block.timestamp is 0 initially (we haven't warped), we can use vm.warp to control baseline.
        vm.warp(1000); // Current timestamp = 1000

        // Now timestamp = 1000
        // First Put: lockTime1 = 200, unlockTime becomes 1000+200=1200
        vm.prank(actor);
        c.Put{value: 0}(lockTime1); // additional 0 deposit to set time

        // Second Put: lockTime2 should be less than lockTime1 to trigger bug. Let lockTime2 = 100.
        // But we fuzz both, so we need to ensure this relationship.
        vm.assume(lockTime2 < lockTime1);
        // Also ensure no overflow
        vm.assume(lockTime2 + 1000 < type(uint256).max);
        vm.assume(lockTime1 + 1000 < type(uint256).max);

        vm.prank(actor);
        c.Put{value: 0}(lockTime2);

        // Correct unlockTime: max(1000+lockTime1, 1000+lockTime2) = 1000+lockTime1
        // Mutant unlockTime: 1000+lockTime2 (overwrites with shorter)
        // Warp to a time between: e.g., 1000+lockTime2 + 1
        // Ensure we warp strictly after mutant unlockTime but before correct unlockTime
        uint256 warpTo = 1000 + lockTime2 + 1;
        vm.assume(warpTo < 1000 + lockTime1);
        vm.warp(warpTo);

        // Attempt Collect with amount <= balance
        collectAmt = bound(collectAmt, 1, 1 ether);

        // Correct contract: should revert because still locked (block.timestamp > unlockTime false)
        // Mutant: should succeed because unlockTime was overwritten to earlier time
        bool success;
        vm.prank(actor);
        try c.Collect(collectAmt) {
            success = true;
        } catch {
            success = false;
        }

        // Assert: Correct contract always reverts (success false) under these conditions.
        // Mutant violates by succeeding (success true) for some inputs.
        assertTrue(!success);
    }
}

contract InvMutTest {
