        require(newMinSum > 0);

        (bool s1,) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", newMinSum));
        initReverted = !s1;

        c.Initialized();

        (bool s2,) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", newMinSum + 1));
        secondSetReverted = !s2;

        assert(!initReverted && secondSetReverted);
    }
}

