    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(uint _val, uint _val2) public returns (bool) {
        c.SetMinSum(_val);
        bool noRevertBeforeInit = true;

        c.Initialized();

        bool revertsAfterInit;
        try c.SetMinSum(_val2) {
            revertsAfterInit = false;
        } catch {
