        bool ok;
        vm.prank(user);
        try c.Collect(_collectAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: if Collect succeeded (ok == true), then current block.timestamp MUST be strictly greater than the caller's unlockTime.
        // Bug mutant may allow Collect even when block.timestamp <= user.unlockTime.
        if (ok) {
            (uint unlockTime, uint balance) = c.Acc(user);
            assertTrue(block.timestamp > unlockTime);
        } else {
            // Collect reverted — always fine.
            assertTrue(true);
        }
    }
}

